SELECT * FROM b_didi_v5_callback_data
WHERE id > #{lastId}
  AND create_time >= curdate()
  AND push_status = 0
  AND status = 0
  AND is_connect = 1
  AND push_type = 1
  AND api_code = #{apiCode}
ORDER BY id ASC LIMIT #{pageSize}

